-- Production composition boundary for G17-G29.
create table public.on_demand_workflow_runs(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,idempotency_key text not null,status text not null default 'queued' check(status in('queued','running','reused','accepted_provisionally','blocked','failed','quarantined')),current_stage text not null default 'requested',input_payload jsonb not null,target_decision_id uuid references public.student_target_decisions(id) on delete restrict,generation_contract_id uuid references public.generation_contracts(id) on delete restrict,reuse_decision_id uuid references public.contract_reuse_decisions(id) on delete restrict,generation_run_id uuid references public.contract_generation_runs(id) on delete restrict,candidate_set_decision_id uuid references public.candidate_set_decisions(id) on delete restrict,selected_serving_version_id uuid references public.generated_content_serving_versions(id) on delete restrict,error_payload jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz,unique(student_id,idempotency_key));
create table public.on_demand_workflow_events(id uuid primary key default gen_random_uuid(),workflow_run_id uuid not null references public.on_demand_workflow_runs(id) on delete cascade,sequence bigint generated always as identity,stage text not null,payload jsonb not null,created_at timestamptz not null default now(),unique(workflow_run_id,sequence));
create index on_demand_workflow_queue_idx on public.on_demand_workflow_runs(status,created_at) where status='queued';
create or replace function public.claim_on_demand_workflow_run()returns public.on_demand_workflow_runs language plpgsql security definer set search_path=public as $$declare r public.on_demand_workflow_runs;begin if auth.role()<>'service_role' then raise exception 'service_role_required';end if;select * into r from public.on_demand_workflow_runs where status='queued' order by created_at for update skip locked limit 1;if r.id is null then return null;end if;update public.on_demand_workflow_runs set status='running',current_stage='claimed',updated_at=now() where id=r.id returning * into r;insert into public.on_demand_workflow_events(workflow_run_id,stage,payload)values(r.id,'claimed',jsonb_build_object('claimedAt',now()));return r;end$$;
revoke all on function public.claim_on_demand_workflow_run() from public;grant execute on function public.claim_on_demand_workflow_run() to service_role;
alter table public.on_demand_workflow_runs enable row level security;alter table public.on_demand_workflow_events enable row level security;create policy workflow_runs_read on public.on_demand_workflow_runs for select using(public.can_view_student(student_id));create policy workflow_events_read on public.on_demand_workflow_events for select using(exists(select 1 from public.on_demand_workflow_runs r where r.id=workflow_run_id and public.can_view_student(r.student_id)));grant select on public.on_demand_workflow_runs,public.on_demand_workflow_events to authenticated;
comment on table public.on_demand_workflow_events is 'Append-only stage ledger composing rollout, targeting, contract, reuse, generation, QA, risk, decision, and serving under one idempotent run.';
